#include <bits/stdc++.h>
using namespace std;

struct Pair {
    int d;
    long long w;
    Pair(int D, long long W) : d(D), w(W) {}
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k;
    cin >> n >> k;
    int a = 0, b = 0;
    for (int i = 0; i < n; i++) {
        int val;
        cin >> val;
        if (val == 50)
            a++;
        else
            b++;
    }

    const long long MOD = 1000000007;
    long long choose[100][100];
    for (int i = 0; i < 100; i++)
        choose[i][0] = 1;
    for (int i = 1; i < 100; i++)
        for (int j = 1; j <= i; j++)
            choose[i][j] = (choose[i - 1][j - 1] + choose[i - 1][j]) % MOD;

    int startMask = 1000000 + 100 * a + b;
    queue<int> q;
    unordered_map<int, Pair> ways;
    q.push(startMask);
    ways[startMask] = Pair(0, 1);

    auto bfs = [&](int mask) {
        int boat = mask / 1000000;
        int nA = (mask % 1000000) / 100;
        int nB = mask % 100;

        if (boat > 0) {
            for (int i = nA; i >= 0 && 50 * (nA - i) <= k; i--) {
                for (int j = nB; j >= 0 && 50 * (nA - i) + 100 * (nB - j) <= k; j--) {
                    if (i != nA || j != nB) {
                        long long edgeWays = choose[nA][i] * choose[nB][j] % MOD;
                        int newMask = 1000000 * (1 - boat) + i * 100 + j;
                        int newD = ways[mask].d + 1;
                        if (ways.find(newMask) == ways.end()) {
                            ways[newMask] = Pair(newD, 0);
                            q.push(newMask);
                        }
                        if (ways[newMask].d == newD) {
                            ways[newMask].w = (ways[newMask].w + ways[mask].w * edgeWays % MOD) % MOD;
                        }
                    }
                }
            }
        } else {
            for (int i = nA; i <= a && 50 * (i - nA) <= k; i++) {
                for (int j = nB; j <= b && 50 * (i - nA) + 100 * (j - nB) <= k; j++) {
                    if (i != nA || j != nB) {
                        long long edgeWays = choose[a - nA][i - nA] * choose[b - nB][j - nB] % MOD;
                        int newMask = 1000000 * (1 - boat) + i * 100 + j;
                        int newD = ways[mask].d + 1;
                        if (ways.find(newMask) == ways.end()) {
                            ways[newMask] = Pair(newD, 0);
                            q.push(newMask);
                        }
                        if (ways[newMask].d == newD) {
                            ways[newMask].w = (ways[newMask].w + ways[mask].w * edgeWays % MOD) % MOD;
                        }
                    }
                }
            }
        }
    };

    while (!q.empty()) {
        int current_mask = q.front();
        q.pop();
        auto it = ways.find(current_mask);
        if (it != ways.end()) {
            bfs(current_mask);
        }
    }

    if (ways.find(0) != ways.end()) {
        cout << ways[0].d << "\n" << ways[0].w << "\n";
    } else {
        cout << -1 << "\n0\n";
    }

    return 0;
}
